output_text:
[
  {
    "id": "must_get_cart",
    "text": "The shopper is obliged to obtain a cart at some point during the trip.",
    "abstraction": {},
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "hasCart"
    }
  },
  {
    "id": "exit_with_cart",
    "text": "The shopper is prohibited from exiting the store without a cart.",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "no_cart_at_item_cell",
    "text": "The shopper is prohibited from being at cell (3,1) while holding or pushing a cart.",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "at(3,1)",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "no_cart_upper_aisle",
    "text": "The shopper is prohibited from taking a cart into the upper aisle cells (3,1) or (3,2).",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          {
            "or": [
              "at(3,1)",
              "at(3,2)"
            ]
          }
        ]
      }
    }
  },
  {
    "id": "no_push_north_from_parking",
    "text": "The shopper is prohibited from moving north from cell (3,3) while holding or pushing a cart.",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "at(3,3)",
          "hasCart",
          "N"
        ]
      }
    }
  },
  {
    "id": "park_cart_at_3_3",
    "text": "If the shopper interacts at cell (3,3) while holding a cart, they are obliged to leave the cart there.",
    "abstraction": {},
    "norm": {
      "type": "obligation",
      "trigger": {
        "and": [
          "at(3,3)",
          "hasCart",
          "INTERACT"
        ]
      },
      "discharge": {
        "and": [
          "at(3,3)",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "reclaim_cart_after_item",
    "text": "After interacting at cell (3,1), the shopper is obliged to regain a cart before finishing.",
    "abstraction": {},
    "norm": {
      "type": "obligation",
      "trigger": {
        "and": [
          "at(3,1)",
          "INTERACT"
        ]
      },
      "discharge": "hasCart"
    }
  },
  {
    "id": "limited_cartless_movement",
    "text": "The shopper is prohibited from moving without a cart except from the entrance start cell or within cells (3,1), (3,2), and (3,3).",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "not": "hasCart"
          },
          "MOVE",
          {
            "not": {
              "or": [
                "at(0,7)",
                "at(3,1)",
                "at(3,2)",
                "at(3,3)"
              ]
            }
          }
        ]
      }
    }
  }
]
